public async Task<IdentityResult> CreateUserWithClaimsAsync(string email, string password, string department)
{
    var user = new ApplicationUser { UserName = email, Email = email };
    var result = await _userManager.CreateAsync(user, password);

    if (result.Succeeded)
    {
        var claims = new List<Claim>
        {
            new Claim("Department", department),
            new Claim("ClearanceLevel", department == "Engineering" ? "5" : "3"),
            new Claim("CanAccessReports", "true", ClaimValueTypes.Boolean)
        };

        await _userManager.AddClaimsAsync(user, claims);
    }

    return result;
}

[Authorize(Policy = "RequireEngineeringDepartment")]
[ApiController]
[Route("api/[controller]")]
public class CodeRepositoryController : ControllerBase
{
    [HttpGet("repositories/{repoId}/secrets")]
    public IActionResult GetRepoSecrets(string repoId)
    {
        var department = User.FindFirst("Department")?.Value;
        var clearance = User.FindFirst("ClearanceLevel")?.Value;

        if (department != "Engineering" || int.Parse(clearance) < 5)
        {
            return Forbid();
        }

        return Ok(new { RepoId = repoId, Secrets = new[] { "API_KEY", "DB_PASSWORD" } });
    }
}

public class DocumentsController : ControllerBase
{
    [HttpGet("{id}")]
    public async Task<IActionResult> GetDocument(string id)
    {
        // Check for specific claim value
        var canRead = User.HasClaim("Permission", "document:read");
        if (!canRead) return Forbid();

        // Check for claim with minimum value
        var clearanceClaim = User.FindFirst("ClearanceLevel")?.Value;
        if (string.IsNullOrEmpty(clearanceClaim) || int.Parse(clearanceClaim) < 3)
        {
            return Forbid();
        }

        var document = await _dbContext.Documents.FindAsync(id);
        return Ok(document);
    }
}

import { jwtDecode } from 'jwt-decode';

interface DecodedToken {
  sub: string;
  email: string;
  Department: string;
  ClearanceLevel: string;
  exp: number;
}

function useClaims() {
  const token = localStorage.getItem('access_token');

  if (!token) return null;

  try {
    const decoded = jwtDecode<DecodedToken>(token);

    // Check expiration
    if (decoded.exp * 1000 < Date.now()) {
      localStorage.removeItem('access_token');
      return null;
    }

    return decoded;
  } catch {
    return null;
  }
}

function DocumentViewer({ documentId }: { documentId: string }) {
  const claims = useClaims();
  const clearance = claims?.ClearanceLevel;

  if (!clearance || parseInt(clearance) < 3) {
    return <div>You need clearance level 3+ to view this document.</div>;
  }

  return <DocumentContent id={documentId} />;
}
